#!/usr/bin/env python3"""Fix collapsed lines in prompts.py."""from pathlib import Pathtarget = Path("bin/agent/prompts.py")content = target.read_text(encoding="utf-8")lines = content.split("\n")new_lines = []i = 0fixed = 0while i < len(lines):    line = lines[i]    s = line.lstrip()    indent = line[:len(line) - len(s)]    # Fix 1: _serialize_element + _write_prompts_xml + _read_tree on one line    if "def _serialize_element" in s and "def _read_tree" in s:        new_lines.append(indent + 'def _serialize_element(elem: ET.Element, indent: str = "") -> str:')        new_lines.append(indent + '    """Serialize an Element to XML string with CDATA for value elements."""')        new_lines.append(indent + '    parts: list[str] = []')        new_lines.append(indent + '    tag = elem.tag')        new_lines.append(indent + '    attrs = ""')        new_lines.append(indent + "    for k, v in elem.attrib.items():")        new_lines.append(indent + '        attrs += f\' {k}="{v}"\'')        new_lines.append(indent + "    children = list(elem)")        new_lines.append(indent + "    has_children = len(children) > 0")        new_lines.append(indent + '    if tag == "value" and elem.text:')        new_lines.append(indent + '        parts.append(f"{indent}<{tag}{attrs}><![CDATA[{elem.text}]]></{tag}>")')        new_lines.append(indent + '        return "".join(parts)')        new_lines.append(indent + "    if not has_children and (elem.text is None or not elem.text.strip()):")        new_lines.append(indent + '        parts.append(f"{indent}<{tag}{attrs} />")')        new_lines.append(indent + "    elif not has_children:")        new_lines.append(indent + '        parts.append(f"{indent}<{tag}{attrs}>{elem.text or \'\'}</{tag}>")')        new_lines.append(indent + "    else:")        new_lines.append(indent + '        parts.append(f"{indent}<{tag}{attrs}>")')        new_lines.append(indent + "        for child in children:")        new_lines.append(indent + '            parts.append("\\n")')        new_lines.append(indent + '            parts.append(_serialize_element(child, indent + "  "))')        new_lines.append(indent + '        parts.append(f"\\n{indent}</{tag}>")')        new_lines.append(indent + '    return "".join(parts)')        new_lines.append("")        new_lines.append("")        new_lines.append(indent + "def _write_prompts_xml(tree: ET.ElementTree, target: Path) -> None:")        new_lines.append(indent + '    """Write the prompts XML tree to target using CDATA for value elements."""')        new_lines.append(indent + "    root = tree.getroot()")        new_lines.append(indent + "    xml_str = '<?xml version=\"1.0\" encoding=\"UTF-8\"?>\\n'")        new_lines.append(indent + "    xml_str += _serialize_element(root)")        new_lines.append(indent + '    xml_str += "\\n"')        new_lines.append(indent + '    target.write_text(xml_str, encoding="utf-8")')        new_lines.append("")        new_lines.append("")        new_lines.append(indent + "def _read_tree(path: Path) -> ET.ElementTree:")        print(f"Fixed _serialize_element at line {i+1}")        fixed += 1        i += 1        continue    # Fix 2: update_base_prompts_from_xml + read_prompts_config on one line    if "def update_base_prompts_from_xml" in s and "def read_prompts_config" in s:        new_lines.append(indent + "def update_base_prompts_from_xml(path: str | Path | None = None) -> Path:")        new_lines.append(indent + '    """Read XML system values and write them back as hardcoded defaults here."""')        new_lines.append(indent + "    target = Path(path).expanduser().resolve() if path else prompts_config_path()")        new_lines.append(indent + "    if not target.exists():")        new_lines.append(indent + '        raise FileNotFoundError(f"prompts_config.xml not found at {target}")')        new_lines.append(indent + "    tree = _read_tree(target)")        new_lines.append(indent + "    root = tree.getroot()")        new_lines.append(indent + "    system, _project = _ensure_sections(root)")        new_lines.append(indent + "    xml_prompts = _read_prompt_section(system)")        new_lines.append(indent + "    if not xml_prompts:")        new_lines.append(indent + "        return target")        new_lines.append(indent + "    this_file = Path(__file__).resolve()")        new_lines.append(indent + '    src_text = this_file.read_text(encoding="utf-8")')        new_lines.append(indent + '    lines_list: list[str] = ["DEFAULT_SYSTEM_PROMPTS: Dict[str, str] = {"]')        new_lines.append(indent + "    seen: set[str] = set()")        new_lines.append(indent + "    for key in DEFAULT_SYSTEM_PROMPTS:")        new_lines.append(indent + "        seen.add(key)")        new_lines.append(indent + "        value = xml_prompts.get(key, DEFAULT_SYSTEM_PROMPTS[key])")        new_lines.append(indent + "        lines_list.append(f\"    {key!r}: {value!r},\")")        new_lines.append(indent + "    for key, value in xml_prompts.items():")        new_lines.append(indent + "        if key in seen:")        new_lines.append(indent + "            continue")        new_lines.append(indent + "        lines_list.append(f\"    {key!r}: {value!r},\")")        new_lines.append(indent + '    lines_list.append("}")')        new_lines.append(indent + '    new_block = "\\n".join(lines_list)')        new_lines.append(indent + "    pattern = re.compile(")        new_lines.append(indent + '        r"DEFAULT_SYSTEM_PROMPTS:\\s*Dict\\[str,\\s*str\\]\\s*=\\s*\\{.*?\\n\\}",')        new_lines.append(indent + "        re.DOTALL,")        new_lines.append(indent + "    )")        new_lines.append(indent + "    if not pattern.search(src_text):")        new_lines.append(indent + '        raise RuntimeError("Could not locate DEFAULT_SYSTEM_PROMPTS dict in prompts.py source")')        new_lines.append(indent + "    updated = pattern.sub(new_block, src_text, count=1)")        new_lines.append(indent + '    this_file.write_text(updated, encoding="utf-8")')        new_lines.append(indent + "    return target")        new_lines.append("")        new_lines.append("")        new_lines.append(indent + "def read_prompts_config(path: str | Path | None = None) -> Dict[str, Dict[str, str]]:")        print(f"Fixed update_base_prompts_from_xml at line {i+1}")        fixed += 1        i += 1        continue    # Fix 3: --update-base CLI on one line    if "--update-base" in s and "--reset-system" in s and "return 0" in s:        new_lines.append(indent + '    if "--update-base" in args:')        new_lines.append(indent + "        print(update_base_prompts_from_xml())")        new_lines.append(indent + "        return 0")        new_lines.append(indent + '    if "--reset-system" in args:')        print(f"Fixed --update-base CLI at line {i+1}")        fixed += 1        i += 1        continue    new_lines.append(line)    i += 1target.write_text("\n".join(new_lines), encoding="utf-8")print(f"Done. Fixed {fixed} blocks. New line count: {len(new_lines)}")